type Lang = 'ru' | 'en' | 'kk' | 'az';
type Gap = 'skill' | 'system' | 'clarity' | 'capacity';
type Plan = 'develop' | 'delegate' | 'automate';
type Skill = { name: string; level: number; criticality: number; evidence: string };
type Values = { salary:number; contribution:number; stability:number; rarity:number };
type Store = Values & { step:number; started:boolean; set:(v:Partial<Values>)=>void; next:()=>void; back:()=>void; reset:()=>void };

const KEY='incore-b2c-market-value-v4';
const TAX_MULTIPLIER=1.43;
const DEFAULT:Values={salary:100000,contribution:250000,stability:1,rarity:1.2};
const useCalc=create<Store>((set)=>({...DEFAULT,step:0,started:false,set:(v)=>set(v),next:()=>set(s=>({step:Math.min(5,s.step+1),started:true})),back:()=>set(s=>({step:Math.max(0,s.step-1)})),reset:()=>set({...DEFAULT,step:0,started:false})}));
const fullCost=(salary:number)=>salary*TAX_MULTIPLIER;
const capacity=(value:number,stability:number,rarity:number)=>value*stability*rarity;
const ratio=(full:number,cap:number)=>cap>0?full/cap:0;
const money=(n:number,lang:Lang='ru')=>{ const locale=lang==='ru'?'ru-RU':lang==='en'?'en-US':lang==='kk'?'kk-KZ':'az-AZ'; const currency=lang==='ru'?'RUB':lang==='en'?'USD':lang==='kk'?'KZT':'AZN'; return new Intl.NumberFormat(locale,{style:'currency',currency,maximumFractionDigits:0}).format(Math.round(n)); };
const currencyLabel=(lang:Lang)=>lang==='ru'?'₽':lang==='en'?'$':lang==='kk'?'₸':'₼';

